package paradox.music.nativeui;
import android.content.*;import android.os.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
/** Bounded local startup timing and main-thread stack samples, written off the UI thread. */
public final class NativeMusicStartupTrace {
 private static final ScheduledExecutorService IO=Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"Ultra-Music-Startup-Timing");t.setDaemon(true);return t;});
 private static File timeline,stalls;private static volatile long start,beat;private static volatile boolean active;private static ScheduledFuture<?> watch;private static final Handler MAIN=new Handler(Looper.getMainLooper());
 private static final Runnable HEARTBEAT=new Runnable(){public void run(){beat=SystemClock.elapsedRealtime();if(active)MAIN.postDelayed(this,500);}};
 public static synchronized void install(Context c){if(timeline==null){timeline=new File(c.getFilesDir(),"ultra-music-timing.txt");stalls=new File(c.getFilesDir(),"ultra-music-main-stalls.txt");}}
 public static synchronized void begin(){start=SystemClock.elapsedRealtime();beat=start;active=true;IO.execute(()->{try{write(timeline,"Startup elapsed timings\n",false);write(stalls,"Main-thread stall snapshots\n",false);}catch(Exception ignored){}});if(watch!=null)watch.cancel(false);MAIN.post(HEARTBEAT);watch=IO.scheduleAtFixedRate(()->sample(),500,500,TimeUnit.MILLISECONDS);event("startup begin");}
 public static void event(String name){if(!active)return;final String text="+"+(SystemClock.elapsedRealtime()-start)+"ms ["+Thread.currentThread().getName()+"] "+name+"\n";IO.execute(()->{try{write(timeline,text,true);}catch(Exception ignored){}});}
 private static void sample(){if(!active)return;long now=SystemClock.elapsedRealtime(),lag=now-beat;if(lag<750||now-start>20000)return;try{StringBuilder s=new StringBuilder("\n+").append(now-start).append("ms heartbeat lag=").append(lag).append("ms\n");Thread main=Looper.getMainLooper().getThread();s.append("MAIN ").append(main.getState()).append('\n');for(StackTraceElement x:main.getStackTrace())s.append("  at ").append(x).append('\n');Map<Thread,StackTraceElement[]> all=Thread.getAllStackTraces();for(Map.Entry<Thread,StackTraceElement[]> e:all.entrySet()){Thread t=e.getKey();if(t==main||t==Thread.currentThread())continue;s.append("Thread ").append(t.getName()).append(' ').append(t.getState()).append('\n');int count=0;for(StackTraceElement x:e.getValue()){if(++count>18)break;s.append("  at ").append(x).append('\n');}}if(stalls.length()<4*1024*1024)write(stalls,s.toString(),true);}catch(Throwable ignored){}}
 public static synchronized void end(){event("startup ended");active=false;if(watch!=null){watch.cancel(false);watch=null;}MAIN.removeCallbacks(HEARTBEAT);}
 public static String readSaved(){return read(timeline,5*1024*1024)+"\n"+read(stalls,5*1024*1024);}
 public static String readSummary(){return read(timeline,32*1024)+"\n"+read(stalls,128*1024);}
 private static String read(File f,int cap){try{if(f==null||!f.exists())return "";ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(f)){byte[] b=new byte[4096];int n;while((n=in.read(b))!=-1&&out.size()<cap)out.write(b,0,n);}return out.toString("UTF-8");}catch(Exception e){return "";}}
 private static void write(File f,String s,boolean append)throws Exception{if(f==null)return;try(FileOutputStream out=new FileOutputStream(f,append)){out.write(s.getBytes("UTF-8"));out.getFD().sync();}}
}
